CREATE OR REPLACE FUNCTION public.register_new_artisan(p_full_name text, p_service_category text, p_city text, p_phone text DEFAULT ''::text, p_description text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_uid           uuid;
  v_artisan_id    uuid;
  v_existing_id   uuid;
  v_full_name     text;
  v_service_cat   text;
  v_city          text;
  v_description   text;
  v_phone         text;
  v_users_updated integer;
  v_prof_updated  integer;
BEGIN

  v_uid := auth.uid();

  IF v_uid IS NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'unauthenticated'
    );
  END IF;

  v_full_name   := trim(COALESCE(p_full_name, ''));
  v_service_cat := trim(COALESCE(p_service_category, ''));
  v_city        := trim(COALESCE(p_city, ''));
  v_description := trim(COALESCE(p_description, ''));
  v_phone       := trim(COALESCE(p_phone, ''));

  IF length(v_full_name) < 3 THEN
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'name_required',
      'message', 'Nom complet requis (3 caractères minimum).'
    );
  END IF;

  IF v_service_cat = '' THEN
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'category_required',
      'message', 'Métier requis.'
    );
  END IF;

  IF v_city = '' THEN
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'city_required',
      'message', 'Ville requise.'
    );
  END IF;

  IF length(v_description) > 500 THEN
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'description_too_long',
      'message', 'Description limitée à 500 caractères.'
    );
  END IF;

  SELECT a.id
  INTO v_existing_id
  FROM public.artisans a
  WHERE a.owner_user_id = v_uid
  LIMIT 1
  FOR UPDATE;

  IF v_existing_id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'ok', true,
      'reason', 'already_registered',
      'artisan_id', v_existing_id
    );
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.users
    WHERE id = v_uid
  ) THEN
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'identity_broken',
      'message', 'Votre compte n''est pas entièrement configuré. Veuillez vous reconnecter.'
    );
  END IF;

  INSERT INTO public.artisans (
    owner_user_id,
    full_name,
    service_category,
    city,
    description,
    phone,
    claimed,
    claim_status,
    onboarding_completed,
    availability,
    verified,
    created_at,
    updated_at
  )
  VALUES (
    v_uid,
    v_full_name,
    v_service_cat,
    v_city,
    v_description,
    NULLIF(v_phone, ''),
    true,
    'approved',
    false,
    'unavailable',
    false,
    now(),
    now()
  )
  RETURNING id INTO v_artisan_id;

  UPDATE public.users
  SET
    role  = 'artisan',
    phone = CASE
      WHEN v_phone != '' THEN v_phone
      ELSE phone
    END
  WHERE id = v_uid
    AND role != 'admin';

  GET DIAGNOSTICS v_users_updated = ROW_COUNT;

  UPDATE public.profiles
  SET
    role  = 'artisan',
    phone = CASE
      WHEN v_phone != '' THEN v_phone
      ELSE phone
    END
  WHERE id = v_uid
    AND (role IS NULL OR role NOT IN ('admin'));

  GET DIAGNOSTICS v_prof_updated = ROW_COUNT;

  RETURN jsonb_build_object(
    'ok', true,
    'reason', 'registered',
    'artisan_id', v_artisan_id,
    'owner_uid', v_uid,
    'profiles_updated', v_prof_updated
  );

EXCEPTION
  WHEN unique_violation THEN

    SELECT a.id
    INTO v_existing_id
    FROM public.artisans a
    WHERE a.owner_user_id = v_uid
    LIMIT 1;

    RETURN jsonb_build_object(
      'ok', true,
      'reason', 'already_registered',
      'artisan_id', COALESCE(v_existing_id, v_artisan_id)
    );

  WHEN OTHERS THEN

    RAISE WARNING
      '[register_new_artisan] unexpected error for uid %: %',
      v_uid,
      SQLERRM;

    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'internal_error'
    );

END;
$function$

CREATE OR REPLACE FUNCTION fixeo_private._fixeo_is_admin()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_caller_id uuid;
  v_result    boolean;
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL THEN
    RETURN false;
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM   public.users u
    WHERE  u.id   = v_caller_id
      AND  u.role = 'admin'
  ) INTO v_result;

  RETURN COALESCE(v_result, false);
END;
$function$

